import re, sys, os, html
from urllib.parse import urlparse, urljoin
root = sys.argv[1]
page = os.path.join(root, "docs", "judges", "index.html")
src = open(page, encoding="utf-8").read()
hrefs = re.findall(r'href="([^"]+)"', src) + re.findall(r'src="([^"]+)"', src)
ids = set(re.findall(r'id="([^"]+)"', src))
GH = "https://github.com/HighnessAtharva/firstrun/blob/main/"
def slug(h):
    s = h.strip().lower()
    s = re.sub(r"[^\w\- ]", "", s)
    return s.replace(" ", "-")
def anchors(path):
    out = set()
    for line in open(path, encoding="utf-8"):
        m = re.match(r"^#+\s+(.*)", line)
        if m: out.add(slug(m.group(1)))
    return out
bad = 0
ext = set()
for h in sorted(set(hrefs)):
    h = html.unescape(h)
    if h.startswith("#"):
        ok = h[1:] in ids
    elif h.startswith(GH):
        rest = h[len(GH):]
        path, _, frag = rest.partition("#")
        fp = os.path.join(root, path)
        ok = os.path.isfile(fp)
        if ok and frag.startswith("L"):
            n = sum(1 for _ in open(fp, encoding="utf-8", errors="ignore"))
            ok = int(frag[1:]) <= n
        elif ok and frag:
            ok = frag in anchors(fp)
    elif h.startswith("https://github.com/HighnessAtharva/firstrun#"):
        ok = h.split("#", 1)[1] in anchors(os.path.join(root, "README.md"))
    elif h.startswith("http"):
        ext.add(h); continue
    else:
        u = urlparse(urljoin("judges/index.html", h))
        p = u.path
        fp = os.path.join(root, "docs", p)
        if p.endswith("/"): fp = os.path.join(fp, "index.html")
        ok = os.path.exists(fp)
    print(("OK  " if ok else "BAD ") + h)
    bad += not ok
print("\nEXTERNAL:")
for e in sorted(ext): print(e)
print("\nbad:", bad)

